/** Native costs/consent/retained components and exact physical return on a stopped earned Library copy. */
final class LibraryServiceRuntime {
 static final String QUEST=ServiceWorkState.LIBRARY;
 static void run(GameTestHelper h)throws Exception{
  var server=h.getLevel().getServer();var id=UUID.nameUUIDFromBytes("PremisesThirdStudent".getBytes(java.nio.charset.StandardCharsets.UTF_8));var p=server.getPlayerList().getPlayer(id);if(p==null)p=ClaimRuntimeTests.vanillaPlayer(h.getLevel(),id,"ThirdStudent");var library=p;verifyArs(h,library);var store=CommerceService.store(server);var proof=server.getWorldPath(LevelResource.ROOT).resolve("library-service-test.nbt");ClaimRuntimeTests.publicResidentAccess(h.getLevel(),library.getUUID());
  if(Files.exists(proof)){var saved=AtomicNbt.read(proof);if(store.professions(id).track(Profession.LIBRARIAN).completedQuestIds().contains(QUEST)){h.assertTrue(store.professions(id).track(Profession.LIBRARIAN).xp()==saved.getLong("xp")+200&&store.serviceWork().jobs(id,QUEST)==3&&store.serviceWork().customers(id,QUEST)==2&&store.itemMailbox(saved.getUUID("customerA")).size()==2&&store.itemMailbox(saved.getUUID("customerB")).size()==1,"Three paid compatible service outputs/two current owners/spent sources/200XP/customer mail restore after restart");CommerceService.verifyReceipt(library);h.assertTrue(h.getLevel().getEntity(project(library).npc())!=null,"Original Orin remains assigned");com.mojang.logging.LogUtils.getLogger().info("LIBRARY_SERVICES_RESTART_PASSED: exact customer mail/source spent/earned200XP/old proofs and Orin persist");h.succeed();return;}
   h.assertTrue(store.serviceWork().jobs(id,QUEST)==1&&server.getPlayerList().getPlayer(saved.getUUID("customerA"))==null,"Partial real service persists with original customer offline");var a=ClaimRuntimeTests.vanillaPlayer(h.getLevel(),saved.getUUID("customerA"),"LibraryCustomerA");var b=ClaimRuntimeTests.vanillaPlayer(h.getLevel(),saved.getUUID("customerB"),"LibraryCustomerB");for(int n=1;n<=2;n++)job(h,library,n==1?a:b,n);counter(library);h.assertTrue(ServiceWorkService.ready(library,QUEST),"Three distinct native outputs returned to two explicit customers satisfy the approved full objective");var q=ProfessionService.review(library,"quest:"+QUEST);ProfessionService.confirm(library,q.nonce());h.assertTrue(store.professions(id).track(Profession.LIBRARIAN).xp()==saved.getLong("xp")+200,"Exactly200Journeyman XP once without inventing other objectives or Master rank");boolean denied=false;try{ProfessionService.review(library,"quest:"+QUEST);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Repeated quest confirmation cannot pay again");CommerceService.checkpoint(library);h.assertTrue(EconomyStore.open(server.getWorldPath(LevelResource.ROOT).resolve("data")).professions(id).equals(store.professions(id)),"Matching native and canonical receipts reopen");com.mojang.logging.LogUtils.getLogger().info("LIBRARY_SERVICES_COMPLETE_PASSED: three actual current-owner consensual native compatible anvil improvements/full book+XP debit/protected enchantments/exact physical returns/2customers/200XP/native reopen; raw inputs and vanilla XP only, no injected source/quest/rank evidence");h.succeed();return;
  }
  h.assertTrue(ServiceWorkService.eligible(library,QUEST)&&store.professions(id).track(Profession.LIBRARIAN).completedQuestIds().contains(Profession.LIBRARIAN.questId(ProfessionRank.APPRENTICE,8)),"Original complete native Apprentice library is required");var a=ClaimRuntimeTests.vanillaPlayer(h.getLevel(),UUID.randomUUID(),"LibraryCustomerA");var b=ClaimRuntimeTests.vanillaPlayer(h.getLevel(),UUID.randomUUID(),"LibraryCustomerB");long xp=store.professions(id).track(Profession.LIBRARIAN).xp();job(h,library,a,0);var saved=new CompoundTag();saved.putLong("xp",xp);saved.putUUID("customerA",a.getUUID());saved.putUUID("customerB",b.getUUID());AtomicNbt.write(proof,saved);CommerceService.checkpoint(library);com.mojang.logging.LogUtils.getLogger().info("LIBRARY_SERVICES_PARTIAL_PASSED: actual current inventory consent/native worn enchanted source/paid native book+XP improvement/preview refusal/exact returned equipment and canonical partial progress persist");h.succeed();
 }
 static ConstructionStore.Project project(ServerPlayer p){return ConstructionService.store(p.server).projects().stream().filter(v->v.blueprint().toString().equals(Profession.LIBRARIAN.buildingId())).findFirst().orElseThrow();}
 static void counter(ServerPlayer p){var project=project(p);var b=BlueprintRegistry.get(project.blueprint(),1);var home=project.origin().offset(b.rotate(b.home(),project.rotation()));BlacksmithRepairRuntime.near(p,home);CommerceService.openResident(p,(ReeveEntity)p.serverLevel().getEntity(project.npc()));}
 static void job(GameTestHelper h,ServerPlayer provider,ServerPlayer owner,int index)throws Exception{job(h,provider,owner,index,QUEST);}
 static void job(GameTestHelper h,ServerPlayer provider,ServerPlayer owner,int index,String expectedQuest)throws Exception{
  var level=provider.serverLevel();var store=CommerceService.store(provider.server);int expectedMail=store.itemMailbox(owner.getUUID()).size()+1;var at=project(provider).origin().offset(500+index*16,0,400);level.getChunkAt(at);h.assertTrue(level.getBlockState(at).isAir(),"Raw wear terrain never replaces existing property");level.setBlock(at.below(),Blocks.STONE.defaultBlockState(),3);level.setBlock(at,Blocks.STONE.defaultBlockState(),3);int slot=-1;for(int i=0;i<9;i++)if(owner.getInventory().getItem(i).isEmpty()){slot=i;break;}h.assertTrue(slot>=0,"Customer has free source slot");owner.getInventory().selected=slot;var input=new ItemStack(Items.IRON_PICKAXE);var efficiency=owner.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow(Enchantments.EFFICIENCY);input.enchant(efficiency,2);owner.setItemInHand(InteractionHand.MAIN_HAND,input);BlacksmithRepairRuntime.near(owner,at);h.assertTrue(owner.gameMode.destroyBlock(at)&&input.getDamageValue()>0&&OwnerRepairServiceRuntime.wearId(input)!=null,"Successful native player removal pays real durability on the enchanted source");var source=OwnerRepairServiceRuntime.wearId(input);counter(provider);counter(owner);var consent=ProfessionService.review(owner,"service_offer:"+provider.getUUID());ProfessionService.confirm(owner,consent.nonce());h.assertTrue(store.serviceWork().owned(owner.getUUID()).stream().anyMatch(c->c.quest().equals(expectedQuest)&&c.provider().equals(provider.getUUID())),"Current provider band, not customer profession or client tags, binds the service purpose");transfer(h,owner,provider,input);
  var site=anvilSite(provider);if(!level.getBlockState(site).is(net.minecraft.tags.BlockTags.ANVIL)){h.assertTrue(level.getBlockState(site).isAir(),"Maintenance worksite never replaces property");var held=provider.getMainHandItem().copy();provider.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.ANVIL));BlacksmithRepairRuntime.near(provider,site);provider.gameMode.useItemOn(provider,level,provider.getMainHandItem(),InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(site.below().getCenter().add(0,.5,0),Direction.UP,site.below(),false));h.assertTrue(provider.getMainHandItem().isEmpty()&&level.getBlockState(site).is(net.minecraft.tags.BlockTags.ANVIL),"Native permitted anvil placement consumes its supplied item");provider.setItemInHand(InteractionHand.MAIN_HAND,held);}
  int found=-1;for(int i=0;i<36;i++)if(source.equals(OwnerRepairServiceRuntime.wearId(provider.getInventory().getItem(i)))){found=i;break;}h.assertTrue(found>=0,"Actual normally transferred input is in provider inventory");var left=provider.getInventory().getItem(found);provider.getInventory().setItem(found,ItemStack.EMPTY);provider.giveExperienceLevels(40);BlacksmithRepairRuntime.near(provider,site);var menu=new AnvilMenu(310+index,provider.getInventory(),ContainerLevelAccess.create(level,site));provider.containerMenu=menu;var book=new ItemStack(Items.ENCHANTED_BOOK);book.enchant(efficiency,2);menu.getSlot(0).set(left);menu.getSlot(1).set(book);var preview=menu.getSlot(2).getItem().copy();var marker=preview.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getCompound(ServiceWorkService.KEY);h.assertTrue(marker.hasUUID("id")&&store.serviceWork().output(marker.getUUID("id")).isEmpty()&&!preview.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().contains(EnchantedToolService.KEY),"A native service preview has no Root authority and cannot also earn a different output purpose");int cost=menu.getCost(),levels=provider.experienceLevel;var output=menu.quickMoveStack(provider,2);h.assertTrue(!output.isEmpty()&&cost>0&&provider.experienceLevel==levels-cost&&menu.getSlot(0).getItem().isEmpty()&&menu.getSlot(1).getItem().isEmpty()&&EnchantmentHelper.getEnchantmentsForCrafting(output).getLevel(efficiency)==3&&output.getDamageValue()==left.getDamageValue(),"Native successful maintenance consumes full donor book and XP, preserves wear and improves the compatible native enchantment");h.assertTrue(store.serviceWork().output(marker.getUUID("id")).orElseThrow().item().equals(output.save(provider.registryAccess())),"Only successful paid native extraction registers the exact canonical output");provider.closeContainer();if(level.getBlockState(site).isAir()){var held=provider.getMainHandItem().copy();provider.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.ANVIL));BlacksmithRepairRuntime.near(provider,site);provider.gameMode.useItemOn(provider,level,provider.getMainHandItem(),InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(site.below().getCenter().add(0,.5,0),Direction.UP,site.below(),false));provider.setItemInHand(InteractionHand.MAIN_HAND,held);}counter(provider);var returned=ProfessionService.review(provider,"service_return:"+marker.getUUID("id"));ProfessionService.confirm(provider,returned.nonce());h.assertTrue(store.serviceWork().spentSource(RepairSavedData.get(provider.server).evidence().identity(),source)&&store.itemMailbox(owner.getUUID()).size()==expectedMail,"Exact physical item leaves provider inventory and credits only its explicit current owner's recoverable mail");
 }
 static BlockPos anvilSite(ServerPlayer p){var project=project(p);var blueprint=BlueprintRegistry.get(project.blueprint(),1);BlockPos free=null;for(int x=2;x<=12;x++)for(int z=2;z<=10;z++){var at=project.origin().offset(blueprint.rotate(new BlockPos(x,1,z),project.rotation()));if(p.serverLevel().getBlockState(at).is(net.minecraft.tags.BlockTags.ANVIL))return at;if(free==null&&p.serverLevel().getBlockState(at).isAir()&&p.serverLevel().getBlockState(at.above()).isAir()&&p.serverLevel().getBlockState(at.below()).isFaceSturdy(p.serverLevel(),at.below(),Direction.UP))free=at;}if(free==null)throw new IllegalStateException("No maintained native bookbinding site");return free;}
 static void transfer(GameTestHelper h,ServerPlayer from,ServerPlayer to,ItemStack expected){counter(from);counter(to);int slot=-1;for(int i=0;i<36;i++)if(ItemStack.matches(from.getInventory().getItem(i),expected)){slot=i;break;}h.assertTrue(slot>=0,"Current owner possesses the exact source");var stack=from.getInventory().getItem(slot);from.getInventory().setItem(slot,ItemStack.EMPTY);var entity=from.drop(stack,false);h.assertTrue(entity!=null,"Actual native item drop");entity.setNoPickUpDelay();entity.playerTouch(to);h.assertTrue(entity.isRemoved()&&java.util.stream.IntStream.range(0,36).anyMatch(i->ItemStack.matches(to.getInventory().getItem(i),expected)),"Native item pickup transfers exact owned equipment without duplication");}

 static void verifyArs(GameTestHelper h,ServerPlayer p)throws Exception{
  if(!net.neoforged.fml.ModList.get().isLoaded("ars_nouveau"))return;
  h.assertTrue(net.neoforged.fml.ModList.get().getModContainerById("ars_nouveau").orElseThrow().getModInfo().getVersion().toString().equals("5.13.3"),"Selected Library profile uses the exact checked Ars5.13.3 artifact");
  var glyph=Class.forName("com.hollingsworth.arsnouveau.common.items.Glyph");var part=Class.forName("com.hollingsworth.arsnouveau.api.spell.AbstractSpellPart");var tier=Class.forName("com.hollingsworth.arsnouveau.api.spell.SpellTier");var ids=new TreeSet<String>();
  for(var item:net.minecraft.core.registries.BuiltInRegistries.ITEM){if(!glyph.isInstance(item))continue;var spell=glyph.getField("spellPart").get(item);var value=part.getMethod("getConfigTier").invoke(spell);if(tier.getField("value").getInt(value)!=2||!(Boolean)part.getMethod("isEnabled").invoke(spell))continue;
   boolean recipe=p.server.getRecipeManager().getRecipes().stream().anyMatch(r->r.value().getResultItem(p.registryAccess()).is(item));if(recipe)ids.add(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(item).toString());}
  h.assertTrue(ids.size()>=4,"Actual native registries/configured enabled Tier2 API and loaded recipes expose at least four real glyphs");com.mojang.logging.LogUtils.getLogger().info("LIBRARY_ARS_API_VALIDATED: exact5.13.3 native boot/current configured Tier2/registry/loaded recipe outputs {}. Catalogue quest remains unimplemented; no activation or acquisition acceptance claimed.",ids);
 }

}
